n34876.content:
\begin{notation}[Standard categorical notation]
  \label{not:standard_category_theory}
  We adopt the following standard categorical notation:
  \begin{itemize}
    \item $\mathsf{Cat}$ denotes the category whose objects are classical categories and whose morphisms
      are classical functors between them.
    \item For a category $\mathsf{C}$, we write $\mathsf{C}^{\mathrm{op}}$ for its opposite category.
    \item When a preordered set $(S, \leq)$ appears in a categorical context, it is understood as
      the category whose objects are the elements of $S$ and where there is a unique morphism from
      $a$ to $b$ if and only if $a \leq b$.
  \end{itemize}
\end{notation}

n34878.content:
\begin{notation}[Extended natural numbers]
  \label{not:extended_naturals}
  We write $\overline{\mathbb{N}}= \mathbb{N}\cup \left\{ \omega \right\}$ for the extended natural numbers, where the top element
  of the inherited order is the symbol $\omega$, that is, $n < \omega$ for every $n \in \mathbb{N}$.
\end{notation}

n34882.content:
\begin{definition}[Single-sorted finite category]
  \label{def:SingleSortedNCategory}
  \uses{def:SingleSortedCategory}
  \lean{HigherCategoryTheory.SingleSorted.NCategory}
  \leanok
  Given a natural number $n \in \mathbb{N}$, a \emph{single-sorted $n$-category} is a single-sorted
  category indexed by the finite set $n = \left\{ 0, 1, \ldots, n-1 \right\}$.
\end{definition}

n34883.content:
\begin{definition}[Pre-single-sorted one-categories lifting]
  \label{def:PreSingleSortedCategoryLift}
  \uses{def:SingleSortedNCategory}
  \lean{HigherCategoryTheory.SingleSorted.PreCategory.lift}
  \leanok
  Any pre-single-sorted $1$-category is, in fact, a single-sorted $1$-category. Since the index
  set $1 = \left\{ 0 \right\}$ has exactly one element, there are no pairs of distinct indices $j < k$, so all
  cross-dimensional axioms are vacuously satisfied.
\end{definition}

n34885.content:
\begin{definition}[Target-based cell]
  \label{def:cell_tg}
  \uses{def:SingleSortedCategory}
  \lean{HigherCategoryTheory.SingleSorted.cell_tg, HigherCategoryTheory.SingleSorted.cells_tg}
  \leanok
  Let $\mathsf{C}$ be a single-sorted $\mathcal{I}$-category and $k \in \mathcal{I}$. A morphism $f \in C$ is a
  \emph{target-based $k$-cell} if and only if
  \[
    \Tg^k (f) = f.
  \]
\end{definition}

n34886.content:
\begin{theorem}[Equivalence of cell definitions]
  \label{thm:cell_sc_iff_cell_tg}
  \uses{def:cell, def:cell_tg}
  \lean{
    HigherCategoryTheory.SingleSorted.cell_sc_iff_cell_tg,
    HigherCategoryTheory.SingleSorted.cells_sc_eq_cells_tg
  }
  \leanok
  Let $\mathsf{C}$ be a single-sorted $\mathcal{I}$-category and $k \in \mathcal{I}$. A morphism $f \in C$ is a
  $k$-cell if and only if it is a target-based $k$-cell.

  It follows that the set of $k$-cells $C_k$ is equal to the set of target-based $k$-cells.
\end{theorem}

n34888.content:
\begin{definition}[Single-sorted omega category]
  \label{def:SingleSortedOmegaCategory}
  \uses{def:cell}
  \lean{HigherCategoryTheory.SingleSorted.OmegaCategory}
  \leanok
  A \emph{single-sorted $\omega$-category} is a single-sorted category indexed by the set of natural
  numbers $\mathbb{N}$, satisfying and additional axiom: for all $f \in C$, there exists a dimension $k \in
  \mathbb{N}$ such that $f$ is a $k$-cell.
\end{definition}

n34890.content:
\begin{construction}[Composition of single-sorted functors]
  \label{def:SingleSortedFunctor_comp}
  \uses{def:SingleSortedFunctor}
  \lean{HigherCategoryTheory.SingleSorted.Functor.comp}
  \leanok
  Let $\mathsf{C}, \mathsf{D}, \mathsf{E}$ be single-sorted $\mathcal{I}$-categories, and let $F \colon \mathsf{C}
  \to \mathsf{D}$ and $G \colon \mathsf{D} \to \mathsf{E}$ be single-sorted $\mathcal{I}$-functors. Then, the
  composition $G \circ F \colon \mathsf{C} \to \mathsf{E}$ is also a single-sorted $\mathcal{I}$-functor.
\end{construction}

n34892.content:
\begin{construction}[Identity single-sorted functor]
  \label{def:SingleSortedFunctor_id}
  \uses{def:SingleSortedFunctor}
  \lean{HigherCategoryTheory.SingleSorted.Functor.id}
  \leanok
  Let $\mathsf{C}$ be a single-sorted $\mathcal{I}$-category. Then, the identity function $\id_C \colon C
  \to C$, written $\id_{\mathsf{C}} \colon \mathsf{C} \to \mathsf{C}$, is a single-sorted $\mathcal{I}$-functor
  from $\mathsf{C}$ to itself.
\end{construction}

n34894.content:
\begin{definition}[Single-sorted finite functor]
  \label{def:SingleSortedNFunctor}
  \uses{def:SingleSortedNCategory, def:SingleSortedFunctor}
  \lean{HigherCategoryTheory.SingleSorted.NFunctor}
  \leanok
  Given a natural number $n \in \mathbb{N}$, a \emph{single-sorted $n$-functor} is a single-sorted
  functor between single-sorted $n$-categories.
\end{definition}

n34895.content:
\begin{definition}[Single-sorted omega functor]
  \label{def:SingleSortedOmegaFunctor}
  \uses{def:SingleSortedOmegaCategory, def:SingleSortedFunctor}
  \lean{HigherCategoryTheory.SingleSorted.OmegaFunctor}
  \leanok
  A \emph{single-sorted $\omega$-functor} is a single-sorted functor between single-sorted
  $\omega$-categories.
\end{definition}

n34896.content:
\begin{construction}[Category of single-sorted categories]
  \label{def:SingleSortedCategory_category}
  \uses{
    def:SingleSortedCategory,
    def:SingleSortedFunctor,
    def:SingleSortedFunctor_comp,
    def:SingleSortedFunctor_id
  }
  \lean{HigherCategoryTheory.SingleSorted.Cat.category}
  \leanok
  The \emph{category of single-sorted $\mathcal{I}$-categories}, denoted by $\mathcal{I}\mathsf{Cat}$, is defined as
  follows:

  \begin{enumerate}
    \item \label{ax:ss_cat_obj} Its objects are single-sorted $\mathcal{I}$-categories.
    \item \label{ax:ss_cat_mor} Its morphisms are single-sorted $\mathcal{I}$-functors between
      single-sorted $\mathcal{I}$-categories.
    \item \label{ax:ss_cat_comp} Composition of morphisms is given by composition of single-sorted
      functors.
    \item \label{ax:ss_cat_id} The identity morphism for each object is given by the identity
      single-sorted functor.
  \end{enumerate}
\end{construction}

n34898.content:
\begin{construction}[Category of single-sorted finite categories]
  \label{def:SingleSortedNCategory_category}
  \uses{
    def:SingleSortedNCategory,
    def:SingleSortedNFunctor,
    def:SingleSortedFunctor_comp,
    def:SingleSortedFunctor_id
  }
  \lean{HigherCategoryTheory.SingleSorted.NCat.category}
  \leanok
  Given a natural number $n \in \mathbb{N}$, the \emph{category of single-sorted $n$-categories}, denoted
  by $n\mathsf{Cat}$, is the particular case of Definition~\ref{def:SingleSortedCategory_category} where
  $\mathcal{I}$ is the finite set $n$. Its objects are single-sorted $n$-categories and its morphisms are
  single-sorted $n$-functors.
\end{construction}

n34899.content:
\begin{proof}
  \leanok
  This is a particular case of Definition~\ref{def:SingleSortedCategory_category}, so the result
  follows immediately.
\end{proof}

n34900.content:
\begin{construction}[Category of single-sorted omega categories]
  \label{def:SingleSortedOmegaCategory_category}
  \uses{
    def:SingleSortedOmegaCategory,
    def:SingleSortedOmegaFunctor,
    def:SingleSortedFunctor_comp,
    def:SingleSortedFunctor_id
  }
  \lean{HigherCategoryTheory.SingleSorted.OmegaCat.category}
  \leanok
  The \emph{category of single-sorted $\omega$-categories}, denoted by $\omega\mathsf{Cat}$, is the
  particular case\footnote{Strictly speaking, $\omega\mathsf{Cat}$ is not exactly a particular case of
  Definition~\ref{def:SingleSortedCategory_category} with $\mathcal{I}= \mathbb{N}$: a single-sorted
  $\omega$-category is not merely a single-sorted $\mathbb{N}$-category, but one satisfying the additional
  axiom that every morphism is a $k$-cell for some $k \in \mathbb{N}$. Thus, the objects of $\omega\mathsf{Cat}$
  form a subclass of those of $\mathbb{N}\mathsf{Cat}$. The categorical structure (composition, identity, and
  laws), however, is inherited directly.} of Definition~\ref{def:SingleSortedCategory_category}
  where $\mathcal{I}$ is the set of natural numbers $\mathbb{N}$. Its objects are single-sorted
  $\omega$-categories and its morphisms are single-sorted $\omega$-functors.
\end{construction}

n34901.content:
\begin{proof}
  \leanok
  This is a particular case of Definition~\ref{def:SingleSortedCategory_category}, so the result
  follows immediately.
\end{proof}

n34902.content:
\begin{notation}
  We extend the notation $n\mathsf{Cat}$ to all $n \in \overline{\mathbb{N}}$, understanding that,
  \begin{itemize}
    \item if $n \in \mathbb{N}$, this is the category $n\mathsf{Cat}$ of
      Definition~\ref{def:SingleSortedNCategory_category}, and
    \item if $n = \omega$, this denotes $\omega\mathsf{Cat}$ of
      Definition~\ref{def:SingleSortedOmegaCategory_category}.
  \end{itemize}
\end{notation}

n34903.content:
\begin{construction}[Discrete single-sorted finite category]
  \label{def:SingleSortedNCategory_discrete}
  \uses{def:SingleSortedNCategory}
  \lean{HigherCategoryTheory.SingleSorted.NCategory.discrete}
  \leanok
  Let $\mathsf{C}$ be a single-sorted $n$-category, and let $m \in \mathbb{N}$ with $n < m$. The
  \emph{discrete $m$-category} of $\mathsf{C}$ is the single-sorted $m$-category $\mathsf{C}^{>m}$ defined
  on the same underlying set $C$, where\footnote{Since no ambiguity arises, we denote the source,
  target, and composition operations of $\mathsf{C}^{>m}$ by the same symbols as those of $\mathsf{C}$.}:

  \begin{itemize}
    \item For $k < n$, the source, target, and composition at dimension $k$ are those of $\mathsf{C}$.
    \item For $n \leq k < m$, the source and target at dimension $k$ are the identity, and
      composition is defined only between equal morphisms, returning the morphism itself.
  \end{itemize}
\end{construction}

n34904.content:
\begin{proof}
  \leanok
  Each axiom either involves only dimensions below $n$, reducing to the corresponding axiom of
  $\mathsf{C}$, or involves a dimension $k \geq n$, where it trivially follows from the fact that all
  operations are trivial.
\end{proof}

n34905.content:
\begin{construction}[Discrete single-sorted omega category]
  \label{def:SingleSortedNCategory_discreteOmega}
  \uses{def:SingleSortedNCategory, def:SingleSortedOmegaCategory}
  \lean{HigherCategoryTheory.SingleSorted.NCategory.discreteOmega}
  \leanok
  Let $\mathsf{C}$ be a single-sorted $n$-category. The \emph{discrete $\omega$-category} of $\mathsf{C}$
  is the single-sorted $\omega$-category $\mathsf{C}^{>\omega}$ defined by the same case distinction as
  in Definition~\ref{def:SingleSortedNCategory_discrete}, now with $k$ ranging over all of $\mathbb{N}$.
\end{construction}

n34906.content:
\begin{proof}
  \leanok
  The single-sorted category axioms follow by the same argument as in
  Definition~\ref{def:SingleSortedNCategory_discrete}. The $\omega$-categorical axiom holds because
  $\Sc^n (f) = f$ for every $f \in C$, so every morphism is an $n$-cell.
\end{proof}

n34907.content:
\begin{construction}[Discrete single-sorted finite functor]
  \label{def:SingleSortedNFunctor_discrete}
  \uses{def:SingleSortedNFunctor, def:SingleSortedNCategory_discrete}
  \lean{HigherCategoryTheory.SingleSorted.NFunctor.discrete}
  \leanok
  Let $\mathsf{C}$ and $\mathsf{D}$ be single-sorted $n$-categories, and let $F \colon \mathsf{C} \to
  \mathsf{D}$ be a single-sorted $n$-functor. For any $m \in \mathbb{N}$ with $n < m$, the same underlying map
  $F$ defines a single-sorted $m$-functor $F^{>m} \colon \mathsf{C}^{>m} \to \mathsf{D}^{>m}$.
\end{construction}

n34908.content:
\begin{proof}
  \leanok
  Each preservation axiom either involves only dimensions below $n$, where it follows from $F$ being
  an $n$-functor, or involves a dimension $k \geq n$, where it trivially follows from the fact that
  all operations are trivial.
\end{proof}

n34909.content:
\begin{construction}[Discrete single-sorted omega functor]
  \label{def:SingleSortedNFunctor_discreteOmega}
  \uses{def:SingleSortedOmegaFunctor, def:SingleSortedNCategory_discreteOmega}
  \lean{HigherCategoryTheory.SingleSorted.NFunctor.discreteOmega}
  \leanok
  Let $\mathsf{C}$ and $\mathsf{D}$ be single-sorted $n$-categories, and let $F \colon \mathsf{C} \to
  \mathsf{D}$ be a single-sorted $n$-functor. The same underlying map $F$ defines a single-sorted
  $\omega$-functor $F^{>\omega} \colon \mathsf{C}^{>\omega} \to \mathsf{D}^{>\omega}$.
\end{construction}

n34910.content:
\begin{proof}
  \leanok
  The argument is identical to that of Definition~\ref{def:SingleSortedNFunctor_discrete}.
\end{proof}

n34911.content:
\begin{construction}[Single-sorted discretization functor]
  \label{def:SingleSortedDiscretizationFunctor}
  \lean{HigherCategoryTheory.SingleSorted.DiscretizationFunctor}
  \uses{
    def:SingleSortedNCategory_discrete,
    def:SingleSortedNCategory_discreteOmega,
    def:SingleSortedNFunctor_discrete,
    def:SingleSortedNFunctor_discreteOmega
  }
  \leanok
  Let $n, m \in \overline{\mathbb{N}}$ with $n \leq m$. The \emph{discretization functor} $\Discrete^{(n, m)}$ from
  $n\mathsf{Cat}$ to $m\mathsf{Cat}$ is the functor that maps every single-sorted $n$-category $\mathsf{C}$ to its
  discrete $m$-category $\mathsf{C}^{>m}$ and every single-sorted $n$-functor $F \colon \mathsf{C} \to
  \mathsf{D}$ to its discrete $m$-functor $F^{>m} \colon \mathsf{C}^{>m} \to \mathsf{D}^{>m}$. If $n = m$,
  then $\Discrete^{(n, n)}$ stands for the identity functor on $n\mathsf{Cat}$.
\end{construction}

n34912.content:
\begin{proof}
  \leanok
  Functoriality follows from the fact that the discrete constructions preserve the underlying map:
  the identity functor on $\mathsf{C}$ yields the identity functor on $\mathsf{C}^{>m}$, and the
  composition of two $n$-functors yields the composition of their discrete $m$-functors.
\end{proof}

n34913.content:
\begin{lemma}
  \label{lem:SingleSorted_underlying_source_is_cell}
  \uses{def:cell}
  \lean{HigherCategoryTheory.SingleSorted.underlying_source_is_cell}
  \leanok
  Let $\mathsf{C}$ be a single-sorted $\mathcal{I}$-category and $m \in \mathcal{I}$. Then, for every $f \in
  \mathsf{C}$ and every $k \in \mathcal{I}$ such that $k < m$, we have that $\Sc^k (f)$ is a $m$-cell in
  $\mathsf{C}$.
\end{lemma}

n34915.content:
\begin{corollary}
  \label{cor:SingleSorted_underlying_source_birestriction}
  \uses{lem:SingleSorted_underlying_source_is_cell}
  \lean{HigherCategoryTheory.SingleSorted.Category.sc_birestriction}
  \leanok
  Let $\mathsf{C}$ be a single-sorted $\mathcal{I}$-category and $m \in \mathcal{I}$. Then, for every $k \in
  \mathcal{I}$ such that $k < m$, the source operation $\Sc^k$ birestricts to the set of $m$-cells $C_m$.
\end{corollary}

n34917.content:
\begin{lemma}
  \label{lem:SingleSorted_underlying_target_is_cell}
  \uses{thm:cell_sc_iff_cell_tg}
  \lean{HigherCategoryTheory.SingleSorted.underlying_target_is_cell}
  \leanok
  Let $\mathsf{C}$ be a single-sorted $\mathcal{I}$-category and $m \in \mathcal{I}$. Then, for every $f \in
  \mathsf{C}$ and every $k \in \mathcal{I}$ such that $k < m$, we have that $\Tg^k (f)$ is a $m$-cell in
  $\mathsf{C}$.
\end{lemma}

n34919.content:
\begin{corollary}
