  \leanok
  Let $\mathsf{C}$ be a single-sorted $\mathcal{I}$-category and $m \in \mathcal{I}$. Then, for every $k \in
  \mathcal{I}$ such that $k < m$, the target operation $\Tg^k$ birestricts to the set of $m$-cells $C_m$.
\end{corollary}

n34921.content:
\begin{lemma}
  \label{lem:SingleSorted_underlying_comp_is_cell}
  \uses{def:cell}
  \lean{HigherCategoryTheory.SingleSorted.underlying_comp_is_cell}
  \leanok
  Let $\mathsf{C}$ be a single-sorted $\mathcal{I}$-category and $m \in \mathcal{I}$. Then, for every $f, g \in
  C_m$ and every $k \in \mathcal{I}$ such that $k < m$, if $f$ and $g$ are composable at dimension $k$,
  then $g \Pcomp^k f$ is an $m$-cell in $\mathsf{C}$.
\end{lemma}

n34923.content:
\begin{corollary}
