n34929.content:
\begin{lemma}
  \label{lem:SingleSorted_underlying_functor_is_cell}
  \uses{def:cell, def:SingleSortedFunctor}
  \lean{HigherCategoryTheory.SingleSorted.underlying_functor_is_cell}
  \leanok
  Let $\mathsf{C}$ and $\mathsf{D}$ be single-sorted $\mathcal{I}$-categories, $F \colon \mathsf{C} \to \mathsf{D}$
  be a single-sorted functor, and $m \in \mathcal{I}$. Then, for every $f \in C_m$ we have that $F(f) \in
