  be a single-sorted functor, and $m \in \mathcal{I}$. Then $F$ birestricts to a function from $C_m$ to
  $D_m$.
\end{corollary}

n34933.content:
\begin{construction}[Underlying single-sorted finite functor]
  \label{def:SingleSortedNFunctor_underlying}
  \uses{def:SingleSortedNCategory_underlying, cor:SingleSorted_underlying_functor_birestriction}
  \lean{HigherCategoryTheory.SingleSorted.NFunctor.underlying}
  \leanok
  Let $\mathsf{C}$ and $\mathsf{D}$ be single-sorted $n$-categories, and let $F \colon \mathsf{C} \to
  \mathsf{D}$ be a single-sorted $n$-functor. For any $m \in \mathbb{N}$ with $m < n$, the birestriction of
  $F$ to the sets of $m$-cells defines a single-sorted $m$-functor $F^{<m} \colon \mathsf{C}^{<m} \to
  \mathsf{D}^{<m}$.
\end{construction}

