\begin{construction}[Composition of many-sorted functors]
  \label{def:ManySortedFunctor_comp}
  \uses{def:ManySortedFunctor}
  \lean{HigherCategoryTheory.ManySorted.Functor.comp}
  \leanok
  Let $\mathsf{C}, \mathsf{D}, \mathsf{E}$ be many-sorted $\mathcal{I}$-categories, and let $F = (F_k)_{k \in
  \mathcal{I}} \colon \mathsf{C} \to \mathsf{D}$ and $G = (G_k)_{k \in \mathcal{I}} \colon \mathsf{D} \to \mathsf{E}$ be
  many-sorted $\mathcal{I}$-functors. Then, the family $G \circ F = (G_k \circ F_k)_{k \in \mathcal{I}} \colon
  \mathsf{C} \to \mathsf{E}$ is also a many-sorted $\mathcal{I}$-functor.
\end{construction}

