  \label{def:ManySortedFunctor_id}
  \uses{def:ManySortedFunctor}
  \lean{HigherCategoryTheory.ManySorted.Functor.id}
  \leanok
  Let $\mathsf{C}$ be a many-sorted $\mathcal{I}$-category. Then, the family of identity functions
  $\id_{\mathsf{C}} = (\id_{C_k})_{k \in \mathcal{I}}$, written $\id_{\mathsf{C}} \colon \mathsf{C} \to \mathsf{C}$,
  is a many-sorted $\mathcal{I}$-functor from $\mathsf{C}$ to itself.
\end{construction}

