  \leanok
  Given a natural number $n \in \mathbb{N}$, the \emph{category of many-sorted $n$-categories}, denoted by
  $n\mathsf{Cat}_{\mathrm{ms}}$, is the particular case of Definition~\ref{def:ManySortedCategory_category} where
  $\mathcal{I}$ is the finite set $n + 1 = \left\{ 0, 1, \ldots, n \right\}$. Its objects are many-sorted
  $n$-categories and its morphisms are many-sorted $n$-functors.
\end{construction}

n34957.content:
\begin{proof}
  \leanok
