n34961.content:
\begin{definition}[Discrete many-sorted finite family]
  \label{def:ManySortedDiscreteFamily}
  \lean{HigherCategoryTheory.ManySorted.NTypeFamily.discrete}
  \uses{def:ManySortedNCategory}
  \leanok
  Let $\mathsf{C}$ be a many-sorted $n$-category on a family $(C_k)_{k \leq n}$, and let $m \in \mathbb{N}$
  with $n < m$. The \emph{discrete finite family} $(C^{>m}_k)_{k \leq m}$ is defined by
  \[
    C^{>m}_k =
    \begin{cases}
      C_k & \text{if } k \leq n, \\
      C_n & \text{if } n < k \leq m.
    \end{cases}
  \]
\end{definition}

n34964.content:
\begin{definition}[Discrete many-sorted omega family]
  \label{def:ManySortedDiscreteOmegaFamily}
  \lean{HigherCategoryTheory.ManySorted.OmegaTypeFamily.discrete}
  \uses{def:ManySortedNCategory}
  \leanok
  Let $\mathsf{C}$ be a many-sorted $n$-category on a family $(C_k)_{k \leq n}$. The \emph{discrete
  omega family} $(C^{>\omega}_k)_{k \in \mathbb{N}}$ is defined by
  \[
    C^{>\omega}_k =
    \begin{cases}
      C_k & \text{if } k \leq n, \\
      C_n & \text{if } k > n.
    \end{cases}
  \]
\end{definition}

n34965.content:
\begin{construction}[Discrete many-sorted omega category]
  \label{def:ManySortedNCategory_discreteOmega}
  \uses{def:ManySortedDiscreteOmegaFamily, def:ManySortedNCategory, def:ManySortedOmegaCategory}
  \lean{HigherCategoryTheory.ManySorted.OmegaCategory.discrete}
  \leanok
  Let $\mathsf{C}$ be a many-sorted $n$-category on a family $(C_k)_{k \leq n}$. The \emph{discrete
  $\omega$-category} of $\mathsf{C}$ is the many-sorted $\omega$-category $\mathsf{C}^{>\omega}$ on the
  discrete omega family $(C^{>\omega}_k)_{k \in \mathbb{N}}$ of
  Definition~\ref{def:ManySortedDiscreteOmegaFamily}, defined by the same case distinction as in
  Definition~\ref{def:ManySortedNCategory_discrete}, now with the indices $k$ and $j$ ranging over
  all of $\mathbb{N}$.
\end{construction}

n34966.content:
\begin{proof}
  \leanok
  The many-sorted category axioms follow by the same argument as in
  Definition~\ref{def:ManySortedNCategory_discrete}.
\end{proof}

n34967.content:
\begin{construction}[Discrete many-sorted finite functor]
  \label{def:ManySortedNFunctor_discrete}
  \uses{def:ManySortedNFunctor, def:ManySortedNCategory_discrete}
  \lean{HigherCategoryTheory.ManySorted.NFunctor.discrete}
  \leanok
  Let $\mathsf{C}$ and $\mathsf{D}$ be many-sorted $n$-categories, and let $F = (F_k)_{k \leq n} \colon
  \mathsf{C} \to \mathsf{D}$ be a many-sorted $n$-functor. For any $m \in \mathbb{N}$ with $n < m$, the family
  $(F^{>m}_k)_{k \leq m}$ defined by
  \[
    F^{>m}_k =
    \begin{cases}
      F_k & \text{if } k \leq n, \\
      F_n & \text{if } n < k \leq m
    \end{cases}
  \]
  is a many-sorted $m$-functor $F^{>m} \colon \mathsf{C}^{>m} \to \mathsf{D}^{>m}$.
\end{construction}

n34969.content:
\begin{construction}[Discrete many-sorted omega functor]
  \label{def:ManySortedNFunctor_discreteOmega}
  \uses{def:ManySortedOmegaFunctor, def:ManySortedNCategory_discreteOmega}
  \lean{HigherCategoryTheory.ManySorted.OmegaFunctor.discrete}
  \leanok
  Let $\mathsf{C}$ and $\mathsf{D}$ be many-sorted $n$-categories, and let $F = (F_k)_{k \leq n} \colon
  \mathsf{C} \to \mathsf{D}$ be a many-sorted $n$-functor. The family $(F^{>\omega}_k)_{k \in \mathbb{N}}$
  defined by
  \[
    F^{>\omega}_k =
    \begin{cases}
      F_k & \text{if } k \leq n, \\
      F_n & \text{if } k > n
    \end{cases}
  \]
  is a many-sorted $\omega$-functor $F^{>\omega} \colon \mathsf{C}^{>\omega} \to \mathsf{D}^{>\omega}$.
\end{construction}

n34970.content:
\begin{proof}
  \leanok
