\end{proof}

n34971.content:
\begin{construction}[Many-sorted discretization functor]
  \label{def:ManySortedDiscretizationFunctor}
  \uses{
    def:ManySortedNCategory_discrete,
    def:ManySortedNCategory_discreteOmega,
    def:ManySortedNFunctor_discrete,
    def:ManySortedNFunctor_discreteOmega
  }
  \lean{HigherCategoryTheory.ManySorted.DiscretizationFunctor}
  \leanok
  Let $n, m \in \overline{\mathbb{N}}$ with $n \leq m$. The \emph{many-sorted discretization functor}
  $\Discrete_{\mathrm{ms}}^{(n, m)}$ from $n\mathsf{Cat}_{\mathrm{ms}}$ to $m\mathsf{Cat}_{\mathrm{ms}}$ is the functor that maps every many-sorted
  $n$-category $\mathsf{C}$ to its discrete $m$-category $\mathsf{C}^{>m}$ and every many-sorted
  $n$-functor $F \colon \mathsf{C} \to \mathsf{D}$ to its discrete $m$-functor $F^{>m} \colon \mathsf{C}^{>m}
  \to \mathsf{D}^{>m}$. If $n = m$, then $\Discrete_{\mathrm{ms}}^{(n, n)}$ stands for the identity functor on
  $n\mathsf{Cat}_{\mathrm{ms}}$.
\end{construction}

n34972.content:
\begin{proof}
  \leanok
  Functoriality follows from the fact that the discrete constructions preserve the underlying maps:
  the identity functor on $\mathsf{C}$ yields the identity functor on $\mathsf{C}^{>m}$, and the
  composition of two $n$-functors yields the composition of their discrete $m$-functors.
\end{proof}

n34973.content:
\begin{construction}[Underlying many-sorted finite category]
  \label{def:ManySortedNCategory_underlying}
  \lean{HigherCategoryTheory.ManySorted.NCategory.underlying}
  \uses{def:ManySortedNCategory}
  \leanok
  Let $\mathsf{C}$ be a many-sorted $n$-category on a family $(C_k)_{k \leq n}$, and let $m \in \mathbb{N}$
  with $m < n$. The \emph{underlying $m$-category} of $\mathsf{C}$ is the many-sorted $m$-category
  $\mathsf{C}^{<m}$ on the restricted family $(C_k)_{k \leq m}$, with the source, target, identity, and
  composition operations at each pair $(k, j)$ with $j < k \leq m$ being those of $\mathsf{C}$.
\end{construction}

n34974.content:
\begin{proof}
  \leanok
  Every axiom of $\mathsf{C}^{<m}$ is an axiom of $\mathsf{C}$ restricted to lower dimensions.
\end{proof}

n34975.content:
