  \label{def:ManySortedOmegaCategory_underlying}
  \lean{HigherCategoryTheory.ManySorted.OmegaCategory.underlying}
  \uses{def:ManySortedOmegaCategory, def:ManySortedNCategory}
  \leanok
  Let $\mathsf{C}$ be a many-sorted $\omega$-category on a family $(C_k)_{k \in \mathbb{N}}$, and let $m \in
  \mathbb{N}$. The \emph{underlying $m$-category} of $\mathsf{C}$ is the many-sorted $m$-category
  $\mathsf{C}^{<m}$ on the restricted family $(C_k)_{k \leq m}$, defined by the same construction as in
  Definition~\ref{def:ManySortedNCategory_underlying}.
\end{construction}

n34976.content:
\begin{proof}
  \leanok
